import { LatticeNode, LatticeLine, AppSettings } from '../types';

// --- Math Helpers ---

// Reduce fraction to simplest form
const gcd = (a: number, b: number): number => b === 0 ? a : gcd(b, a % b);

// Returns the largest prime factor of n (ignoring 2)
const getMaxPrime = (n: number): number => {
  let temp = n;
  while (temp % 2 === 0 && temp > 1) temp /= 2;
  if (temp === 1) return 1;

  let maxP = 1;
  let d = 3;
  while (d * d <= temp) {
    while (temp % d === 0) {
      maxP = d;
      temp /= d;
    }
    d += 2;
  }
  if (temp > 1) maxP = temp;
  return maxP;
};

// Fraction Class for integer math
class Fraction {
  n: number;
  d: number;

  constructor(n: number, d: number) {
    this.n = n;
    this.d = d;
  }

  mul(other: Fraction): Fraction {
    return new Fraction(this.n * other.n, this.d * other.d);
  }

  normalize(): Fraction {
    // Bring into 1/1 to 2/1 range (approx)
    // Actually, we usually want 1 <= ratio < 2
    let nn = this.n;
    let dd = this.d;

    // Simplification first
    const divisor = gcd(nn, dd);
    nn /= divisor;
    dd /= divisor;

    // Octave reduce
    while (nn >= 2 * dd) dd *= 2;
    while (nn < dd) nn *= 2;

    return new Fraction(nn, dd);
  }
}

// --- Vectors for Projection ---
// Adjust these to change the visual "tilt"
// Screen coords: +y is Down.
const VECTORS = {
  3: { x: 0, y: -90 },    // North (Up)
  5: { x: 75, y: -50 },   // Northeast (Right-Up)
  7: { x: 60, y: 50 },    // Southeast (Right-Down)
  11: { x: -60, y: -40 }, // Northwest (Left-Up)
  13: { x: -50, y: 60 },  // Southwest (Left-Down)
};

const PRIMES = [3, 5, 7, 11, 13];
const PRIME_RATIOS = {
  3: new Fraction(3, 2),
  5: new Fraction(5, 4),
  7: new Fraction(7, 4),
  11: new Fraction(11, 8),
  13: new Fraction(13, 8),
};

// --- Generation ---

export const generateLattice = (settings: AppSettings): { nodes: LatticeNode[], lines: LatticeLine[] } => {
  const nodes: Map<string, LatticeNode> = new Map();
  const queue: { coords: number[], ratio: Fraction }[] = [];

  // Start at Origin
  // Coords: [exp3, exp5, exp7, exp11, exp13]
  const originCoords = [0, 0, 0, 0, 0];
  const originFrac = new Fraction(1, 1);
  queue.push({ coords: originCoords, ratio: originFrac });

  // Add origin node immediately
  nodes.set(originCoords.join(','), createNode(originCoords, originFrac));

  const MAX_NODES = 2000; // Safety cap
  let processedCount = 0;

  // Set of visited coord strings to prevent duplicates in queue
  const visited = new Set<string>();
  visited.add(originCoords.join(','));

  while (queue.length > 0 && processedCount < MAX_NODES) {
    const current = queue.shift()!;
    processedCount++;

    const { coords, ratio } = current;
    const currentDist = coords.reduce((acc, val) => acc + Math.abs(val), 0);

    // Expand
    if (currentDist < settings.latticeShells) {
      PRIMES.forEach((prime, idx) => {
        // Skip if limit not enabled
        if (prime === 7 && !settings.enabledLimits[7]) return;
        if (prime === 11 && !settings.enabledLimits[11]) return;
        if (prime === 13 && !settings.enabledLimits[13]) return;

        // Try +1 direction
        const nextPos = [...coords];
        nextPos[idx] += 1;
        const posKey = nextPos.join(',');

        if (!visited.has(posKey)) {
          visited.add(posKey);
          const nextRatio = ratio.mul(PRIME_RATIOS[prime as keyof typeof PRIME_RATIOS]).normalize();
          const node = createNode(nextPos, nextRatio);
          nodes.set(posKey, node);
          queue.push({ coords: nextPos, ratio: nextRatio });
        }

        // Try -1 direction
        const nextNeg = [...coords];
        nextNeg[idx] -= 1;
        const negKey = nextNeg.join(',');

        if (!visited.has(negKey)) {
          visited.add(negKey);
          // Inverse ratio
          const pRat = PRIME_RATIOS[prime as keyof typeof PRIME_RATIOS];
          const invRatio = new Fraction(pRat.d, pRat.n);
          const nextRatio = ratio.mul(invRatio).normalize();
          const node = createNode(nextNeg, nextRatio);
          nodes.set(negKey, node);
          queue.push({ coords: nextNeg, ratio: nextRatio });
        }
      });
    }
  }

  // Generate Lines
  const lines: LatticeLine[] = [];
  const nodeList = Array.from(nodes.values());

  // Sort nodes for rendering order (Consonance: Low limit first -> High Z-Index)
  // But DOM renders bottom-up. So first in array = behind.
  // User wants "top to bottom layer 2,3,5...".
  // So 13 limit should be drawn first (bottom layer), 1 limit last (top layer).
  nodeList.sort((a, b) => b.maxPrime - a.maxPrime);

  // Generate connections
  nodeList.forEach(node => {
    PRIMES.forEach((prime, idx) => {
       // Look for neighbor in +1 direction only (to avoid double lines)
       const neighborCoords = [...node.coords];
       neighborCoords[idx] += 1;
       const neighborKey = neighborCoords.join(',');
       const neighbor = nodes.get(neighborKey);

       if (neighbor) {
         lines.push({
           id: `${node.id}-${neighbor.id}`,
           x1: node.x,
           y1: node.y,
           x2: neighbor.x,
           y2: neighbor.y,
           limit: prime
         });
       }
    });
  });

  return { nodes: nodeList, lines };
};

const createNode = (coords: number[], frac: Fraction): LatticeNode => {
  // Project coordinates to 2D
  let x = 0;
  let y = 0;

  // 3-limit (Index 0)
  x += coords[0] * VECTORS[3].x;
  y += coords[0] * VECTORS[3].y;

  // 5-limit (Index 1)
  x += coords[1] * VECTORS[5].x;
  y += coords[1] * VECTORS[5].y;

  // 7-limit (Index 2)
  x += coords[2] * VECTORS[7].x;
  y += coords[2] * VECTORS[7].y;

  // 11-limit (Index 3)
  x += coords[3] * VECTORS[11].x;
  y += coords[3] * VECTORS[11].y;

  // 13-limit (Index 4)
  x += coords[4] * VECTORS[13].x;
  y += coords[4] * VECTORS[13].y;

  const n = frac.n;
  const d = frac.d;
  const val = n / d;

  const limitTop = getMaxPrime(n);
  const limitBottom = getMaxPrime(d);
  const maxPrime = Math.max(limitTop, limitBottom);

  return {
    id: coords.join(','),
    label: `${n}/${d}`,
    n, d,
    ratio: val,
    x, y,
    limitTop,
    limitBottom,
    maxPrime,
    coords
  };
};

import React, { useEffect, useRef, useState, useLayoutEffect } from 'react';
import { AppSettings, LatticeNode, LatticeLine } from '../types';
import { generateLattice } from '../services/LatticeService';
import AudioEngine from '../services/AudioEngine';

interface Props {
  settings: AppSettings;
  audioEngine: AudioEngine;
}

interface ActiveTouch {
  id: number;
  nodeId: string;
  startX: number;
  startY: number;
  currentX: number;
  currentY: number;
  lockedAxis: 'x' | 'y' | null;
}

const TonalityDiamond: React.FC<Props> = ({ settings, audioEngine }) => {
  const scrollContainerRef = useRef<HTMLDivElement>(null);
  const contentRef = useRef<HTMLDivElement>(null);

  const [data, setData] = useState<{ nodes: LatticeNode[], lines: LatticeLine[] }>({ nodes: [], lines: [] });
  const [activeTouches, setActiveTouches] = useState<Map<number, ActiveTouch>>(new Map());
  const [dimensions, setDimensions] = useState({ width: 0, height: 0, minX: 0, minY: 0 });

  // Generate Data
  useEffect(() => {
    const result = generateLattice(settings);
    setData(result);

    // Calculate bounding box
    let minX = Infinity, maxX = -Infinity, minY = Infinity, maxY = -Infinity;
    if (result.nodes.length === 0) {
        minX = -500; maxX = 500; minY = -500; maxY = 500;
    } else {
        result.nodes.forEach(n => {
            if (n.x < minX) minX = n.x;
            if (n.x > maxX) maxX = n.x;
            if (n.y < minY) minY = n.y;
            if (n.y > maxY) maxY = n.y;
        });
    }

    // Add padding
    const pad = 400;
    setDimensions({
        width: (maxX - minX) + pad * 2,
        height: (maxY - minY) + pad * 2,
        minX: minX - pad,
        minY: minY - pad
    });

  }, [settings]);

  // Initial Center Scroll
  useLayoutEffect(() => {
    if (scrollContainerRef.current && dimensions.width > 0) {
        // Center the view on (0,0) relative to minX/minY
        // Origin is at x = -minX, y = -minY
        const centerX = -dimensions.minX;
        const centerY = -dimensions.minY;

        scrollContainerRef.current.scrollLeft = centerX - scrollContainerRef.current.clientWidth / 2;
        scrollContainerRef.current.scrollTop = centerY - scrollContainerRef.current.clientHeight / 2;
    }
  }, [dimensions]);

  useEffect(() => {
    audioEngine.setPolyphony(settings.polyphony);
  }, [settings.polyphony, audioEngine]);

  const handlePointerDown = (e: React.PointerEvent, node: LatticeNode) => {
    e.preventDefault();
    e.stopPropagation();
    audioEngine.startVoice(e.pointerId, node.ratio);
    setActiveTouches(prev => {
      const newMap = new Map(prev);
      newMap.set(e.pointerId, {
        id: e.pointerId,
        nodeId: node.id,
        startX: e.clientX,
        startY: e.clientY,
        currentX: e.clientX,
        currentY: e.clientY,
        lockedAxis: null
      });
      return newMap;
    });
    (e.target as HTMLElement).setPointerCapture(e.pointerId);
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    if (!settings.isPitchBendEnabled || !activeTouches.has(e.pointerId)) return;
    const touch = activeTouches.get(e.pointerId)!;

    let lockedAxis = touch.lockedAxis;
    if (!lockedAxis) {
      const dx = Math.abs(e.clientX - touch.startX);
      const dy = Math.abs(e.clientY - touch.startY);
      if (dx > 5 || dy > 5) {
        lockedAxis = dx > dy ? 'x' : 'y';
      }
    }

    const sensitivity = 2.0; 
    let delta = 0;
    if (lockedAxis === 'x') delta = e.clientX - touch.startX;
    if (lockedAxis === 'y') delta = -(e.clientY - touch.startY);

    let detune = delta * sensitivity;
    if (settings.isPitchSnapEnabled) {
       const snapStrength = 20;
       if (Math.abs(detune) < snapStrength) detune = 0;
    }

    audioEngine.bendVoice(e.pointerId, detune);

    setActiveTouches(prev => {
        const newMap = new Map(prev);
        newMap.set(e.pointerId, { ...touch, currentX: e.clientX, currentY: e.clientY, lockedAxis });
        return newMap;
    });
  };

  const handlePointerUp = (e: React.PointerEvent) => {
    audioEngine.stopVoice(e.pointerId);
    setActiveTouches(prev => {
      const newMap = new Map(prev);
      newMap.delete(e.pointerId);
      return newMap;
    });
  };

  const getColor = (limit: number): string => settings.colors[limit] || '#64748b';

  const baseSize = 60 * settings.buttonSizeScale;
  const touches: ActiveTouch[] = Array.from(activeTouches.values());

  return (
    <div 
        ref={scrollContainerRef}
        className="w-full h-full overflow-auto bg-slate-950 relative"
        style={{ touchAction: 'none' }}
    >
        <div 
            ref={contentRef}
            className="relative"
            style={{ 
                width: dimensions.width, 
                height: dimensions.height,
            }}
        >
            {/* SVG Layer for Lines */}
            <svg className="absolute top-0 left-0 w-full h-full pointer-events-none" style={{ zIndex: 0 }}>
                {data.lines.map(line => {
                    // Coordinates relative to container
                    const x1 = line.x1 - dimensions.minX;
                    const y1 = line.y1 - dimensions.minY;
                    const x2 = line.x2 - dimensions.minX;
                    const y2 = line.y2 - dimensions.minY;
                    const color = getColor(line.limit);

                    return (
                        <line 
                            key={line.id}
                            x1={x1} y1={y1} x2={x2} y2={y2}
                            stroke={color}
                            strokeWidth={2}
                            strokeOpacity={0.3}
                        />
                    );
                })}
            </svg>

            {/* Nodes Layer */}
            {data.nodes.map((node) => {
                const activeTouch = touches.find(t => t.nodeId === node.id);
                const isActive = !!activeTouch;

                let transformX = 0;
                let transformY = 0;

                if (isActive && activeTouch && settings.isPitchBendEnabled) {
                    if (activeTouch.lockedAxis === 'x') transformX = activeTouch.currentX - activeTouch.startX;
                    if (activeTouch.lockedAxis === 'y') transformY = activeTouch.currentY - activeTouch.startY;
                }

                const left = node.x - dimensions.minX;
                const top = node.y - dimensions.minY;

                // Color logic
                const cTop = getColor(node.limitTop);
                const cBottom = getColor(node.limitBottom);
                const background = `linear-gradient(to bottom, ${cTop} 50%, ${cBottom} 50%)`;

                return (
                    <div
                        key={node.id}
                        className="absolute flex items-center justify-center shadow-md cursor-pointer touch-none select-none"
                        style={{
                            left: `${left}px`,
                            top: `${top}px`,
                            width: `${baseSize}px`,
                            height: `${baseSize}px`,
                            background: background,
                            borderRadius: settings.buttonShape,
                            transform: `translate(-50%, -50%) translate(${transformX}px, ${transformY}px)`,
                            boxShadow: isActive ? `0 0 25px white` : '0 4px 6px rgba(0,0,0,0.6)',
                            zIndex: isActive ? 100 : 50 - node.maxPrime, // Consonance layering
                            opacity: isActive ? 1 : 0.95,
                            border: '2px solid rgba(255,255,255,0.3)'
                        }}
                        onPointerDown={(e) => handlePointerDown(e, node)}
                        onPointerMove={handlePointerMove}
                        onPointerUp={handlePointerUp}
                        onPointerLeave={handlePointerUp}
                        onPointerCancel={handlePointerUp}
                    >
                        <div className="flex flex-col w-full h-full text-white font-bold leading-none text-shadow-sm">
                            <span className="flex-1 flex items-center justify-center pt-1" style={{ fontSize: '11px' }}>{node.n}</span>
                            <span className="flex-1 flex items-center justify-center pb-1 border-t border-white/20" style={{ fontSize: '11px' }}>{node.d}</span>
                        </div>
                    </div>
                );
            })}
        </div>
    </div>
  );
};

export default TonalityDiamond;

import React, { useRef, useState } from 'react';
import { AppSettings, ButtonShape } from '../types';

interface Props {
  isOpen: boolean;
  onClose: () => void;
  settings: AppSettings;
  updateSettings: (s: AppSettings) => void;
  onSave: () => void;
  onLoad: (file: File) => void;
}

const SettingsModal: React.FC<Props> = ({ isOpen, onClose, settings, updateSettings, onSave, onLoad }) => {
  const fileInputRef = useRef<HTMLInputElement>(null);

  if (!isOpen) return null;

  const handleChange = (key: keyof AppSettings, value: any) => {
    updateSettings({ ...settings, [key]: value });
  };

  const handleLimitToggle = (limit: 7 | 11 | 13) => {
    updateSettings({
      ...settings,
      enabledLimits: {
        ...settings.enabledLimits,
        [limit]: !settings.enabledLimits[limit]
      }
    });
  };

  const handleColorChange = (limit: number, color: string) => {
    updateSettings({
      ...settings,
      colors: { ...settings.colors, [limit]: color }
    });
  };

  return (
    <div className="fixed inset-0 bg-black/80 z-50 flex items-center justify-center backdrop-blur-sm">
      <div className="bg-slate-800 p-6 rounded-xl w-[90%] max-w-2xl max-h-[90vh] overflow-y-auto text-slate-200 shadow-2xl border border-slate-700 flex flex-col">
        <div className="flex justify-between items-center mb-6">
          <h2 className="text-2xl font-bold text-white">Lattice Configuration</h2>
          <button onClick={onClose} className="text-slate-400 hover:text-white">✕</button>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
            {/* Dimensions & Limits */}
            <div className="space-y-6">
                <h3 className="font-semibold text-blue-400 border-b border-slate-700 pb-1">Dimensions</h3>

                <div>
                    <label className="block text-sm font-semibold mb-2">Lattice Depth (Shells)</label>
