            {/* Color/Select Layer Button */}
            <button 
              onClick={() => bringToFront(limit)}
              className={`w-10 h-10 rounded-lg shadow-md border-2 transition-all transform active:scale-95 flex items-center justify-center font-bold text-xs text-shadow`}
              style={{ 
                backgroundColor: color, 
                borderColor: isTop ? 'white' : 'transparent',
                boxShadow: isTop ? '0 0 10px rgba(255,255,255,0.5)' : 'none',
                opacity: visible ? 1 : 0.2
              }}
            >
              {limit}
            </button>
          </div>
        );
      })}
    </div>
  );
};

export default LimitLayerControls;

import React, { useEffect, useRef, useState, useLayoutEffect } from 'react';
import { AppSettings, LatticeNode, LatticeLine } from '../types';
import { generateLattice } from '../services/LatticeService';
import AudioEngine from '../services/AudioEngine';

interface Props {
  settings: AppSettings;
  audioEngine: AudioEngine;
  onLimitInteraction: (limit: number) => void;
}

interface ActiveTouch {
  id: number;
  nodeId: string;
  startX: number;
  startY: number;
  currentX: number;
  currentY: number;
  lockedAxis: 'x' | 'y' | null;
}

const TonalityDiamond: React.FC<Props> = ({ settings, audioEngine, onLimitInteraction }) => {
  const scrollContainerRef = useRef<HTMLDivElement>(null);
  const contentRef = useRef<HTMLDivElement>(null);

  const [data, setData] = useState<{ nodes: LatticeNode[], lines: LatticeLine[] }>({ nodes: [], lines: [] });
  const [activeTouches, setActiveTouches] = useState<Map<number, ActiveTouch>>(new Map());
  const [dimensions, setDimensions] = useState({ width: 0, height: 0, minX: 0, minY: 0 });

  // Generate Data
  useEffect(() => {
    const result = generateLattice(settings);
    // Filter out nodes based on hiddenLimits (visual hiding)
    const visibleNodes = result.nodes.filter(n => !settings.hiddenLimits.includes(n.maxPrime));
    const visibleLines = result.lines.filter(l => !settings.hiddenLimits.includes(l.limit));

    // We also need to filter lines if their endpoints are hidden, but that's complex without looking up nodes.
    // However, if the line limit is hidden, the axis is hidden. 
    // If a node is hidden (e.g. 5-limit hidden), we should probably hide lines connected to it?
    // For now, let's trust that hiding the axis line and the node is enough.

    setData({ nodes: visibleNodes, lines: visibleLines });

    // Calculate bounding box
    let minX = Infinity, maxX = -Infinity, minY = Infinity, maxY = -Infinity;
    if (visibleNodes.length === 0) {
        minX = -500; maxX = 500; minY = -500; maxY = 500;
    } else {
        visibleNodes.forEach(n => {
            if (n.x < minX) minX = n.x;
            if (n.x > maxX) maxX = n.x;
            if (n.y < minY) minY = n.y;
            if (n.y > maxY) maxY = n.y;
        });
    }

    // Add padding
    const pad = 400;
    setDimensions({
        width: (maxX - minX) + pad * 2,
        height: (maxY - minY) + pad * 2,
        minX: minX - pad,
        minY: minY - pad
    });

  }, [settings]);

  // Initial Center Scroll
  useLayoutEffect(() => {
    if (scrollContainerRef.current && dimensions.width > 0) {
        // Only center if we haven't scrolled yet? Or on explicit reset.
        // For now, just do it on mount or significant dimension change.
        // We'll check if scroll is 0.
        if (scrollContainerRef.current.scrollLeft === 0 && scrollContainerRef.current.scrollTop === 0) {
            const centerX = -dimensions.minX;
            const centerY = -dimensions.minY;
            scrollContainerRef.current.scrollLeft = centerX - scrollContainerRef.current.clientWidth / 2;
            scrollContainerRef.current.scrollTop = centerY - scrollContainerRef.current.clientHeight / 2;
        }
    }
  }, [dimensions]);

  useEffect(() => {
    audioEngine.setPolyphony(settings.polyphony);
  }, [settings.polyphony, audioEngine]);

  const handlePointerDown = (e: React.PointerEvent, node: LatticeNode) => {
    e.preventDefault();
    e.stopPropagation();

    // Trigger Layer Reordering
    onLimitInteraction(node.maxPrime);

    audioEngine.startVoice(e.pointerId, node.ratio);
    setActiveTouches(prev => {
      const newMap = new Map(prev);
      newMap.set(e.pointerId, {
        id: e.pointerId,
        nodeId: node.id,
        startX: e.clientX,
        startY: e.clientY,
        currentX: e.clientX,
        currentY: e.clientY,
        lockedAxis: null
      });
      return newMap;
    });
    (e.target as HTMLElement).setPointerCapture(e.pointerId);
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    if (!settings.isPitchBendEnabled || !activeTouches.has(e.pointerId)) return;
    const touch = activeTouches.get(e.pointerId)!;

    let lockedAxis = touch.lockedAxis;
    if (!lockedAxis) {
      const dx = Math.abs(e.clientX - touch.startX);
      const dy = Math.abs(e.clientY - touch.startY);
      if (dx > 5 || dy > 5) {
        lockedAxis = dx > dy ? 'x' : 'y';
      }
    }

    const sensitivity = 2.0; 
    let delta = 0;
    if (lockedAxis === 'x') delta = e.clientX - touch.startX;
    if (lockedAxis === 'y') delta = -(e.clientY - touch.startY);

    let detune = delta * sensitivity;
    if (settings.isPitchSnapEnabled) {
       const snapStrength = 20;
       if (Math.abs(detune) < snapStrength) detune = 0;
    }

    audioEngine.bendVoice(e.pointerId, detune);

    setActiveTouches(prev => {
        const newMap = new Map(prev);
        newMap.set(e.pointerId, { ...touch, currentX: e.clientX, currentY: e.clientY, lockedAxis });
        return newMap;
    });
  };

  const handlePointerUp = (e: React.PointerEvent) => {
    audioEngine.stopVoice(e.pointerId);
    setActiveTouches(prev => {
      const newMap = new Map(prev);
      newMap.delete(e.pointerId);
      return newMap;
    });
  };

  const getColor = (limit: number): string => settings.colors[limit] || '#64748b';

  const baseSize = 60 * settings.buttonSizeScale;
  const touches: ActiveTouch[] = Array.from(activeTouches.values());

  return (
    <div 
        ref={scrollContainerRef}
        className="w-full h-full overflow-auto bg-slate-950 relative"
        style={{ touchAction: 'none' }}
    >
        <div 
            ref={contentRef}
            className="relative"
            style={{ 
                width: dimensions.width, 
                height: dimensions.height,
            }}
        >
            {/* SVG Layer for Lines */}
            <svg className="absolute top-0 left-0 w-full h-full pointer-events-none" style={{ zIndex: 0 }}>
                {data.lines.map(line => {
                    const x1 = line.x1 - dimensions.minX;
                    const y1 = line.y1 - dimensions.minY;
                    const x2 = line.x2 - dimensions.minX;
                    const y2 = line.y2 - dimensions.minY;
                    const color = getColor(line.limit);

                    return (
                        <line 
                            key={line.id}
                            x1={x1} y1={y1} x2={x2} y2={y2}
                            stroke={color}
                            strokeWidth={2}
                            strokeOpacity={0.3}
                        />
                    );
                })}
            </svg>

            {/* Nodes Layer */}
            {data.nodes.map((node) => {
                const activeTouch = touches.find(t => t.nodeId === node.id);
                const isActive = !!activeTouch;

                let transformX = 0;
                let transformY = 0;

                if (isActive && activeTouch && settings.isPitchBendEnabled) {
                    if (activeTouch.lockedAxis === 'x') transformX = activeTouch.currentX - activeTouch.startX;
                    if (activeTouch.lockedAxis === 'y') transformY = activeTouch.currentY - activeTouch.startY;
                }

                const left = node.x - dimensions.minX;
                const top = node.y - dimensions.minY;

                // Color logic
                const cTop = getColor(node.limitTop);
                const cBottom = getColor(node.limitBottom);
                const background = `linear-gradient(to bottom, ${cTop} 50%, ${cBottom} 50%)`;

                // Z-Index Logic based on Layer Order
                // Find index in layerOrder array. Higher index = Higher Z.
                // Base Z is 10. Active is 100.
                const layerIndex = settings.layerOrder.indexOf(node.maxPrime);
                const zIndex = isActive ? 100 : (10 + layerIndex);

                return (
                    <div
                        key={node.id}
                        className="absolute flex items-center justify-center shadow-md cursor-pointer touch-none select-none transition-transform"
                        style={{
                            left: `${left}px`,
                            top: `${top}px`,
                            width: `${baseSize}px`,
                            height: `${baseSize}px`,
                            background: background,
                            borderRadius: settings.buttonShape,
                            transform: `translate(-50%, -50%) translate(${transformX}px, ${transformY}px) scale(${isActive ? 1.1 : 1})`,
                            boxShadow: isActive ? `0 0 25px white` : '0 4px 6px rgba(0,0,0,0.6)',
                            zIndex: zIndex,
                            opacity: isActive ? 1 : 0.95,
                            border: '2px solid rgba(255,255,255,0.3)'
                        }}
                        onPointerDown={(e) => handlePointerDown(e, node)}
                        onPointerMove={handlePointerMove}
                        onPointerUp={handlePointerUp}
                        onPointerLeave={handlePointerUp}
                        onPointerCancel={handlePointerUp}
                    >
                        <div className="flex flex-col w-full h-full text-white font-bold leading-none text-shadow-sm">
                            <span className="flex-1 flex items-center justify-center pt-1" style={{ fontSize: '11px' }}>{node.n}</span>
                            <span className="flex-1 flex items-center justify-center pb-1 border-t border-white/20" style={{ fontSize: '11px' }}>{node.d}</span>
                        </div>
                    </div>
                );
            })}
        </div>
    </div>
  );
};

export default TonalityDiamond;

import React, { useState, useEffect, useRef } from 'react';
import TonalityDiamond from './components/TonalityDiamond';
import SettingsModal from './components/SettingsModal';
import SynthControls from './components/SynthControls';
import FloatingControls from './components/FloatingControls';
import LimitLayerControls from './components/LimitLayerControls';
import AudioEngine from './services/AudioEngine';
import { AppSettings, SynthPreset } from './types';
import { DEFAULT_COLORS, DEFAULT_SETTINGS, DEFAULT_PRESET } from './constants';

const App: React.FC = () => {
  const [settings, setSettings] = useState<AppSettings>(DEFAULT_SETTINGS);
  const [preset, setPreset] = useState<SynthPreset>(DEFAULT_PRESET);
  const [masterVolume, setMasterVolume] = useState(0.8);

  // Modals
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [isSynthOpen, setIsSynthOpen] = useState(false);

  // Audio Engine Singleton Ref
  const engineRef = useRef<AudioEngine>(new AudioEngine(DEFAULT_PRESET));

  // Init Engine updates
  useEffect(() => {
    engineRef.current.setMasterVolume(masterVolume);
  }, [masterVolume]);

  useEffect(() => {
    engineRef.current.setPreset(preset);
  }, [preset]);

  const handleLimitInteraction = (limit: number) => {
    // Move touched limit to the end of the array (front)
    // Only if it's not already at the front
    if (settings.layerOrder[settings.layerOrder.length - 1] !== limit) {
      const newOrder = settings.layerOrder.filter(l => l !== limit);
      newOrder.push(limit);
      setSettings(prev => ({ ...prev, layerOrder: newOrder }));
    }
  };

  // XML Handlers
  const saveSettingsToXML = () => {
    const data = {
      settings,
      preset,
    };
    const xml = `
      <PrismaTonalConfig>
        <Settings>${JSON.stringify(settings)}</Settings>
        <Preset>${JSON.stringify(preset)}</Preset>
      </PrismaTonalConfig>
    `;
    const blob = new Blob([xml], { type: 'text/xml' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = 'prismatonal_config.xml';
    a.click();
    URL.revokeObjectURL(url);
  };

  const loadSettingsFromXML = (file: File) => {
    const reader = new FileReader();
    reader.onload = (e) => {
      const text = e.target?.result as string;
      // Basic extraction (Assuming valid format from save)
      try {
        // Regex hack for simplicity in this demo environment, ideally use DOMParser
        const settingsMatch = text.match(/<Settings>(.*?)<\/Settings>/);
        const presetMatch = text.match(/<Preset>(.*?)<\/Preset>/);

        if (settingsMatch && settingsMatch[1]) {
           const parsedSettings = JSON.parse(settingsMatch[1]);
           // Ensure colors are merged correctly to avoid missing keys
           setSettings({ ...parsedSettings, colors: { ...DEFAULT_COLORS, ...parsedSettings.colors } });
        }
        if (presetMatch && presetMatch[1]) {
           setPreset(JSON.parse(presetMatch[1]));
        }
        setIsSettingsOpen(false);
      } catch (err) {
        alert("Failed to parse XML config file.");
      }
    };
    reader.readAsText(file);
  };

  return (
    <div className="relative w-screen h-screen overflow-hidden bg-slate-900 font-sans text-white">

      {/* Top Bar */}
      <div className="absolute top-0 left-0 w-full p-4 flex justify-between items-center z-40 pointer-events-none">
        <h1 className="text-xl font-bold tracking-widest text-slate-500 opacity-50">PRISMATONAL</h1>
        <div className="flex gap-2 pointer-events-auto">
          <button 
            onClick={() => setIsSynthOpen(true)}
            className="bg-slate-800/80 hover:bg-indigo-600 px-4 py-2 rounded-lg backdrop-blur transition border border-white/10"
          >
            Synth
          </button>
          <button 
            onClick={() => setIsSettingsOpen(true)}
            className="bg-slate-800/80 hover:bg-slate-600 px-4 py-2 rounded-lg backdrop-blur transition border border-white/10"
          >
            Settings
          </button>
        </div>
      </div>

      {/* Main Canvas */}
      <TonalityDiamond 
        settings={settings} 
        audioEngine={engineRef.current} 
        onLimitInteraction={handleLimitInteraction}
      />

      {/* Floating UI */}
      <FloatingControls 
        volume={masterVolume}
        setVolume={setMasterVolume}
        onPanic={() => engineRef.current.stopAll()}
        pitchOffLocked={settings.pitchOffLocked}
        volumeLocked={settings.volumeLocked}
      />

      <LimitLayerControls 
        settings={settings}
        updateSettings={setSettings}
      />

      {/* Modals */}
      <SettingsModal 
        isOpen={isSettingsOpen} 
        onClose={() => setIsSettingsOpen(false)}
        settings={settings}
        updateSettings={setSettings}
        onSave={saveSettingsToXML}
        onLoad={loadSettingsFromXML}
      />

      <SynthControls 
        isOpen={isSynthOpen}
        onClose={() => setIsSynthOpen(false)}
        preset={preset}
        onChange={setPreset}
      />
    </div>
  );
};

export default App;

