                    <div className={`transition-opacity ${settings.isVoiceLeadingEnabled ? 'opacity-100' : 'opacity-50 pointer-events-none'}`}>
                        <label className="block text-xs mb-1 text-slate-400">Dimming Strength</label>
                         <input 
                            type="range" min="0.1" max="0.5" step="0.05" 
                            value={settings.voiceLeadingStrength}
                            onChange={(e) => handleChange('voiceLeadingStrength', parseFloat(e.target.value))}
                            className="w-full h-1 bg-slate-700 rounded-lg appearance-none cursor-pointer"
                        />
                    </div>
                </div>

                <div>
                     <label className="flex items-center space-x-2 mb-2 p-2 bg-slate-900/50 rounded border border-teal-500/30">
                        <input type="checkbox" checked={settings.isMomentumEnabled} onChange={(e) => handleChange('isMomentumEnabled', e.target.checked)} className="w-5 h-5 rounded border-slate-600 text-teal-500 focus:ring-teal-500" />
                        <span className="font-semibold text-teal-300">Momentum / Latch</span>
                    </label>
                </div>

                <div className="border-t border-slate-700 pt-4">
                    <label className="block text-sm mb-1">Button Size ({settings.buttonSizeScale.toFixed(1)}x)</label>
                    <input 
                        type="range" min="0.5" max="2.0" step="0.1" 
                        value={settings.buttonSizeScale}
                        onChange={(e) => handleChange('buttonSizeScale', parseFloat(e.target.value))}
                        className="w-full h-2 bg-slate-700 rounded-lg appearance-none cursor-pointer"
                    />
                </div>

                <div>
                     <label className="block text-sm mb-1">Button Shape</label>
                     <div className="flex gap-2">
                       <button 
                         onClick={() => handleChange('buttonShape', ButtonShape.CIRCLE)}
                         className={`px-3 py-1 rounded ${settings.buttonShape === ButtonShape.CIRCLE ? 'bg-indigo-600' : 'bg-slate-700'}`}
                       >Circle</button>
                       <button 
                         onClick={() => handleChange('buttonShape', ButtonShape.DIAMOND)}
                         className={`px-3 py-1 rounded ${settings.buttonShape === ButtonShape.DIAMOND ? 'bg-indigo-600' : 'bg-slate-700'}`}
                       >Diamond</button>
                     </div>
                </div>

                <div className="space-y-2">
                    <span className="block text-sm font-semibold">Limit Colors</span>
                    <div className="flex gap-3 flex-wrap">
                      {[1, 3, 5, 7, 11, 13].map(limit => (
                        <div key={limit} className="flex flex-col items-center">
                          <input 
                            type="color" 
                            value={settings.colors[limit] || '#ffffff'} 
                            onChange={(e) => handleColorChange(limit, e.target.value)}
                            className="w-8 h-8 rounded cursor-pointer border-none"
                          />
                          <span className="text-xs mt-1 text-slate-400">{limit}</span>
                        </div>
                      ))}
                    </div>
                </div>

                 <div className="grid grid-cols-2 gap-2 text-sm">
                 <label className="flex items-center space-x-2">
                   <input type="checkbox" checked={settings.isPitchBendEnabled} onChange={(e) => handleChange('isPitchBendEnabled', e.target.checked)} />
                   <span>Pitch Bend</span>
                 </label>
                 <label className="flex items-center space-x-2">
                   <input type="checkbox" checked={settings.isPitchSnapEnabled} onChange={(e) => handleChange('isPitchSnapEnabled', e.target.checked)} />
                   <span>Snap</span>
                 </label>
              </div>

            </div>
        </div>

        {/* Persistence Actions */}
        <div className="mt-8 flex gap-4 border-t border-slate-700 pt-4">
          <button onClick={onSave} className="flex-1 bg-green-600 hover:bg-green-700 py-2 rounded font-semibold transition shadow-lg">
            Export Config
          </button>
          <button onClick={() => fileInputRef.current?.click()} className="flex-1 bg-slate-600 hover:bg-slate-700 py-2 rounded font-semibold transition shadow-lg">
            Import Config
          </button>
          <input 
            type="file" 
            ref={fileInputRef} 
            className="hidden" 
            accept=".xml" 
            onChange={(e) => {
              if (e.target.files?.[0]) onLoad(e.target.files[0]);
            }} 
          />
        </div>

      </div>
    </div>
  );
};

export default SettingsModal;

import React, { useEffect, useRef, useState, useLayoutEffect } from 'react';
import { AppSettings, LatticeNode, LatticeLine } from '../types';
import { generateLattice, getHarmonicDistance } from '../services/LatticeService';
import AudioEngine from '../services/AudioEngine';

interface Props {
  settings: AppSettings;
  audioEngine: AudioEngine;
  onLimitInteraction: (limit: number) => void;
}

interface ActiveTouch {
  id: number;
  nodeId: string;
  startX: number;
  startY: number;
  currentX: number;
  currentY: number;
  lockedAxis: 'x' | 'y' | null;
}

interface LatchedVoice {
  voiceId: number;
  nodeId: string;
}

const TonalityDiamond: React.FC<Props> = ({ settings, audioEngine, onLimitInteraction }) => {
  const scrollContainerRef = useRef<HTMLDivElement>(null);
  const contentRef = useRef<HTMLDivElement>(null);

  const [data, setData] = useState<{ nodes: LatticeNode[], lines: LatticeLine[] }>({ nodes: [], lines: [] });
  const [activeTouches, setActiveTouches] = useState<Map<number, ActiveTouch>>(new Map());
  const [latchedVoices, setLatchedVoices] = useState<Map<string, number>>(new Map()); // nodeId -> voiceId

  const [lastPlayedCoords, setLastPlayedCoords] = useState<number[]>([0, 0, 0, 0, 0]); 

  const [hasCentered, setHasCentered] = useState(false);

  useEffect(() => {
    const result = generateLattice(settings);
    const visibleNodes = result.nodes.filter(n => !settings.hiddenLimits.includes(n.maxPrime));
    const visibleLines = result.lines.filter(l => !settings.hiddenLimits.includes(l.limit));
    setData({ nodes: visibleNodes, lines: visibleLines });
  }, [settings]);

  useLayoutEffect(() => {
    if (scrollContainerRef.current && !hasCentered) {
        const center = settings.canvasSize / 2;
        const viewportW = scrollContainerRef.current.clientWidth;
        const viewportH = scrollContainerRef.current.clientHeight;

        scrollContainerRef.current.scrollLeft = center - viewportW / 2;
        scrollContainerRef.current.scrollTop = center - viewportH / 2;
        setHasCentered(true);
    }
  }, [settings.canvasSize, hasCentered]);

  useEffect(() => {
    audioEngine.setPolyphony(settings.polyphony);
  }, [settings.polyphony, audioEngine]);

  const handlePointerDown = (e: React.PointerEvent, node: LatticeNode) => {
    e.preventDefault();
    e.stopPropagation();

    // Tap to stop Latched Voice
    if (latchedVoices.has(node.id)) {
        const voiceId = latchedVoices.get(node.id)!;
        audioEngine.stopVoice(voiceId);
        setLatchedVoices(prev => {
            const next = new Map(prev);
            next.delete(node.id);
            return next;
        });
        return;
    }

    onLimitInteraction(node.maxPrime);
    setLastPlayedCoords(node.coords);

    audioEngine.startVoice(e.pointerId, node.ratio);
    setActiveTouches(prev => {
      const newMap = new Map(prev);
      newMap.set(e.pointerId, {
        id: e.pointerId,
        nodeId: node.id,
        startX: e.clientX,
        startY: e.clientY,
        currentX: e.clientX,
        currentY: e.clientY,
        lockedAxis: null
      });
      return newMap;
    });
    (e.target as HTMLElement).setPointerCapture(e.pointerId);
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    if (!activeTouches.has(e.pointerId)) return;
    const touch = activeTouches.get(e.pointerId)!;

    // --- Smooth Transition (Legato) Logic ---
    const centerOffset = settings.canvasSize / 2;
    const spacing = settings.buttonSpacingScale;

    // Check collision with other nodes
    const rect = contentRef.current?.getBoundingClientRect();
    if (rect) {
       const canvasX = e.clientX - rect.left;
       const canvasY = e.clientY - rect.top;

       const hitRadius = (60 * settings.buttonSizeScale) * 0.8; 

       // Find potential target
       const targetNode = data.nodes.find(n => {
          if (n.id === touch.nodeId) return false;
          // Node coords in canvas space
          const nx = n.x * spacing + centerOffset;
          const ny = n.y * spacing + centerOffset;
          const dist = Math.sqrt(Math.pow(nx - canvasX, 2) + Math.pow(ny - canvasY, 2));
          return dist < hitRadius;
       });

       if (targetNode) {
          // Trigger Handoff
          audioEngine.glideVoice(e.pointerId, targetNode.ratio, 0.05);
          onLimitInteraction(targetNode.maxPrime);
          setLastPlayedCoords(targetNode.coords);

          setActiveTouches(prev => {
             const newMap = new Map(prev);
             newMap.set(e.pointerId, {
                 ...touch,
                 nodeId: targetNode.id,
                 // Reset anchor to current position so bend becomes 0 relative to new node
                 startX: e.clientX,
                 startY: e.clientY,
                 currentX: e.clientX,
                 currentY: e.clientY,
                 lockedAxis: null
             });
             return newMap;
          });
          return; // Skip bend logic for this frame
       }
    }

    // --- Pitch Bend Logic ---
    if (settings.isPitchBendEnabled) {
        let lockedAxis = touch.lockedAxis;
        if (!lockedAxis) {
        const dx = Math.abs(e.clientX - touch.startX);
        const dy = Math.abs(e.clientY - touch.startY);
        if (dx > 5 || dy > 5) {
            lockedAxis = dx > dy ? 'x' : 'y';
        }
        }

        const sensitivity = 2.0; 
        let delta = 0;
        if (lockedAxis === 'x') delta = e.clientX - touch.startX;
        if (lockedAxis === 'y') delta = -(e.clientY - touch.startY);

        let detune = delta * sensitivity;
        if (settings.isPitchSnapEnabled) {
            const snapStrength = 20;
            if (Math.abs(detune) < snapStrength) detune = 0;
        }

        audioEngine.bendVoice(e.pointerId, detune);

        setActiveTouches(prev => {
            const newMap = new Map(prev);
            newMap.set(e.pointerId, { ...touch, currentX: e.clientX, currentY: e.clientY, lockedAxis });
            return newMap;
        });
    }
  };

  const handlePointerUp = (e: React.PointerEvent) => {
    const touch = activeTouches.get(e.pointerId);

    // --- Momentum Logic ---
    if (settings.isMomentumEnabled && touch && settings.isPitchBendEnabled) {
        const deltaX = e.clientX - touch.startX;
        const deltaY = e.clientY - touch.startY;
        const dist = Math.sqrt(deltaX*deltaX + deltaY*deltaY);

        // If dragged significantly, latch
        if (dist > 30) {
            const currentNode = data.nodes.find(n => n.id === touch.nodeId);
            if (currentNode) {
                setLatchedVoices(prev => {
                    const newMap = new Map(prev);
                    newMap.set(touch.nodeId, e.pointerId);
                    return newMap;
                });

                audioEngine.glideVoice(e.pointerId, currentNode.ratio, 0.5); 

                setActiveTouches(prev => {
                    const newMap = new Map(prev);
                    newMap.delete(e.pointerId);
                    return newMap;
                });
                return;
            }
        }
    }

    audioEngine.stopVoice(e.pointerId);
    setActiveTouches(prev => {
      const newMap = new Map(prev);
      newMap.delete(e.pointerId);
      return newMap;
    });
  };

  const getColor = (limit: number): string => settings.colors[limit] || '#64748b';

  const baseSize = 60 * settings.buttonSizeScale;
  const touches: ActiveTouch[] = Array.from(activeTouches.values());
  const centerOffset = settings.canvasSize / 2;
  const spacing = settings.buttonSpacingScale;

  // Collect active nodes (touched or latched) for visualization
  const activeNodeIds = new Set([...touches.map(t => t.nodeId), ...latchedVoices.keys()]);

  // Helper to render curved lines for active nodes
  const renderCurvedLines = () => {
     const paths: React.ReactElement[] = [];

     activeNodeIds.forEach(activeId => {
         const activeNode = data.nodes.find(n => n.id === activeId);
         if (!activeNode) return;

         const startX = activeNode.x * spacing + centerOffset;
         const startY = activeNode.y * spacing + centerOffset;

         // Find neighbors
         const neighborLines = data.lines.filter(l => 
            (l.x1 === activeNode.x && l.y1 === activeNode.y) || 
            (l.x2 === activeNode.x && l.y2 === activeNode.y)
         );

         neighborLines.forEach(line => {
             // Identify neighbor coords
             const isStart = (line.x1 === activeNode.x && line.y1 === activeNode.y);
             const nx = isStart ? line.x2 : line.x1;
             const ny = isStart ? line.y2 : line.y1;
             const neighborX = nx * spacing + centerOffset;
             const neighborY = ny * spacing + centerOffset;

             // Find neighbor node object to check ratio
             const neighborNode = data.nodes.find(n => n.x === nx && n.y === ny);
             if (!neighborNode) return;

             // Curve Logic
             const midX = (startX + neighborX) / 2;
             const midY = (startY + neighborY) / 2;

             // Vector from Start to End
             const vx = neighborX - startX;
             const vy = neighborY - startY;

             const isHigher = neighborNode.ratio > activeNode.ratio;
             const curveScale = 0.2; // 20% of length

             let cpx = midX - vy * curveScale * (isHigher ? 1 : -1);
             let cpy = midY + vx * curveScale * (isHigher ? 1 : -1);

             // SVG Path Q = Quadratic Bezier
             const pathD = `M ${startX} ${startY} Q ${cpx} ${cpy} ${neighborX} ${neighborY}`;
             const color = getColor(line.limit);

             paths.push(
                <path 
                    key={`curve-${activeId}-${line.id}`}
                    d={pathD}
                    stroke={color}
                    strokeWidth={4}
                    strokeLinecap="round"
                    fill="none"
                    className="opacity-60 animate-pulse"
                />
             );
         });
     });
     return paths;
  };

  return (
    <div 
        ref={scrollContainerRef}
        className="w-full h-full overflow-auto bg-slate-950 relative"
        style={{ touchAction: 'none' }}
    >
        <div 
            ref={contentRef}
            className="relative"
            style={{ 
                width: settings.canvasSize, 
                height: settings.canvasSize,
            }}
        >
            {/* SVG Layer for Lines */}
            <svg className="absolute top-0 left-0 w-full h-full pointer-events-none" style={{ zIndex: 0 }}>
                {/* Standard Grid Lines */}
                {data.lines.map(line => {
                    const x1 = line.x1 * spacing + centerOffset;
                    const y1 = line.y1 * spacing + centerOffset;
                    const x2 = line.x2 * spacing + centerOffset;
                    const y2 = line.y2 * spacing + centerOffset;
                    const color = getColor(line.limit);

                    return (
                        <line 
                            key={line.id}
                            x1={x1} y1={y1} x2={x2} y2={y2}
                            stroke={color}
                            strokeWidth={2}
                            strokeOpacity={0.2}
                        />
                    );
                })}

                {/* Voice Leading Curves */}
                {renderCurvedLines()}
            </svg>

            {/* Nodes Layer */}
            {data.nodes.map((node) => {
                const activeTouch = touches.find(t => t.nodeId === node.id);
                const isLatched = latchedVoices.has(node.id);
                const isActive = !!activeTouch || isLatched;

                let transformX = 0;
                let transformY = 0;

                // Apply bend offset visual only for touch
                if (activeTouch && settings.isPitchBendEnabled) {
                    if (activeTouch.lockedAxis === 'x') transformX = activeTouch.currentX - activeTouch.startX;
                    if (activeTouch.lockedAxis === 'y') transformY = activeTouch.currentY - activeTouch.startY;
                }

                const left = node.x * spacing + centerOffset;
                const top = node.y * spacing + centerOffset;

                const cTop = getColor(node.limitTop);
                const cBottom = getColor(node.limitBottom);
                const background = `linear-gradient(to bottom, ${cTop} 50%, ${cBottom} 50%)`;

                const layerIndex = settings.layerOrder.indexOf(node.maxPrime);
                const zIndex = isActive ? 100 : (10 + layerIndex);

                // --- Voice Leading Visualization Logic ---
                let scale = 1.0;
                let opacity = 0.95;

                if (settings.isVoiceLeadingEnabled) {
                  const dist = getHarmonicDistance(node.coords, lastPlayedCoords);
                  if (!isActive) {
                    const falloff = settings.voiceLeadingStrength; 
                    const visibility = Math.max(0.25, 1 - (dist * falloff));
                    scale = Math.max(0.4, visibility);
                    opacity = Math.max(0.15, visibility);
                  } else {
                    scale = 1.2; 
                    opacity = 1.0;
                  }
                } else {
                    scale = isActive ? 1.2 : 1.0;
                    opacity = isActive ? 1.0 : 0.95;
                }

                return (
                    <div
                        key={node.id}
                        className="absolute flex items-center justify-center shadow-md cursor-pointer touch-none select-none transition-all duration-300 ease-out"
                        style={{
                            left: `${left}px`,
                            top: `${top}px`,
                            width: `${baseSize}px`,
                            height: `${baseSize}px`,
                            background: background,
                            borderRadius: settings.buttonShape,
                            transform: `translate(-50%, -50%) translate(${transformX}px, ${transformY}px) scale(${scale})`,
                            boxShadow: isActive ? `0 0 35px white` : '0 4px 6px rgba(0,0,0,0.6)',
                            zIndex: zIndex,
                            opacity: opacity,
                            border: isLatched ? '3px solid white' : '2px solid rgba(255,255,255,0.3)',
                            filter: isActive ? 'brightness(1.3)' : 'none'
                        }}
                        onPointerDown={(e) => handlePointerDown(e, node)}
                        onPointerMove={handlePointerMove}
                        onPointerUp={handlePointerUp}
                        onPointerLeave={handlePointerUp}
                        onPointerCancel={handlePointerUp}
                    >
                        <div className={`flex flex-col w-full h-full text-white font-bold leading-none text-shadow-sm transition-opacity ${scale < 0.6 ? 'opacity-0' : 'opacity-100'}`}>
                            <span className="flex-1 flex items-center justify-center pt-1" style={{ fontSize: '11px' }}>{node.n}</span>
                            <span className="flex-1 flex items-center justify-center pb-1 border-t border-white/20" style={{ fontSize: '11px' }}>{node.d}</span>
                        </div>
                    </div>
                );
            })}
        </div>
    </div>
  );
};

export default TonalityDiamond;

export enum LimitType {
  LIMIT_3 = 3,
  LIMIT_5 = 5,
  LIMIT_7 = 7,
  LIMIT_11 = 11,
  LIMIT_13 = 13,
}

export enum WaveformType {
  SINE = 'sine',
  SQUARE = 'square',
  SAWTOOTH = 'sawtooth',
  TRIANGLE = 'triangle',
}

export enum ButtonShape {
  CIRCLE = '50%',
  DIAMOND = '0%',
}

export interface LimitColorMap {
  [key: number]: string;
}

export interface AppSettings {
  latticeShells: number; // 1 to 20
  enabledLimits: {
    7: boolean;
    11: boolean;
    13: boolean;
  };
  // Visible toggle for lower limits
  hiddenLimits: number[]; 

  layerOrder: number[]; // Array of limit numbers, index 0 = back, last index = front

  maxND: number; // Complexity limit: Maximum Numerator or Denominator

  // Voice Leading / Focus Mode
  isVoiceLeadingEnabled: boolean;
  voiceLeadingStrength: number; // 0 to 1, higher means stricter falloff
  isMomentumEnabled: boolean; // Retain motion and latch on release

  buttonSizeScale: number; // 0.5 to 2.0
  buttonSpacingScale: number; // 0.5 to 5.0
  canvasSize: number; // Width/Height of the scrollable area in pixels (e.g. 3000, 5000)
  buttonShape: ButtonShape;
  colors: LimitColorMap;
  isPitchBendEnabled: boolean;
  isPitchSnapEnabled: boolean;
  polyphony: number;
  pitchOffLocked: boolean;
  volumeLocked: boolean;
}

export interface SynthPreset {
  id: number;
  name: string;
  waveform: WaveformType;
  attack: number;
  decay: number;
  sustain: number;
  release: number;
  gain: number;
  filterCutoff: number; // Hz
  reverbMix: number; // 0 to 1
}

export interface LatticeNode {
  id: string; // Coordinate key "0,0,0,0,0:oct"
  ratio: number; // Absolute Frequency multiplier (including octave)
  n: number; // Numerator (adjusted for octave)
  d: number; // Denominator (adjusted for octave)
  label: string; 
  x: number; // Screen X
  y: number; // Screen Y
  limitTop: number; 
  limitBottom: number;
  maxPrime: number; // For Z-sorting
  coords: number[]; // [p3, p5, p7, p11, p13]
  octave: number; // -2, -1, 0, 1, 2
}

export interface LatticeLine {
  id: string;
  x1: number;
  y1: number;
  x2: number;
  y2: number;
  limit: number;
}

export interface ActiveVoice {
  id: number; // Pointer ID
  nodeId: string;
  stop: () => void;
  setDetune: (cents: number) => void;
}

import { LatticeNode, LatticeLine, AppSettings } from '../types';

// --- Math Helpers ---

const gcd = (a: number, b: number): number => b === 0 ? a : gcd(b, a % b);

const getMaxPrime = (n: number): number => {
  let temp = n;
  while (temp % 2 === 0 && temp > 1) temp /= 2;
  if (temp === 1) return 1;

  let maxP = 1;
  let d = 3;
  while (d * d <= temp) {
    while (temp % d === 0) {
      maxP = d;
      temp /= d;
    }
    d += 2;
  }
  if (temp > 1) maxP = temp;
  return maxP;
};

class Fraction {
  n: number;
  d: number;

  constructor(n: number, d: number) {
    this.n = n;
    this.d = d;
  }

  mul(other: Fraction): Fraction {
    return new Fraction(this.n * other.n, this.d * other.d);
  }

  normalize(): Fraction {
    let nn = this.n;
    let dd = this.d;

    const divisor = gcd(nn, dd);
    nn /= divisor;
    dd /= divisor;

    while (nn >= 2 * dd) dd *= 2;
    while (nn < dd) nn *= 2;

    return new Fraction(nn, dd);
  }

  // Adjust fraction by octave shift
  shiftOctave(octave: number): Fraction {
    let nn = this.n;
    let dd = this.d;
    if (octave > 0) {
        nn *= Math.pow(2, octave);
    } else if (octave < 0) {
        dd *= Math.pow(2, Math.abs(octave));
    }
    // Simplify again to keep numbers clean
    const divisor = gcd(nn, dd);
    return new Fraction(nn / divisor, dd / divisor);
  }
}

// X-Axis projection vectors (Harmonic Width)
// Y-Axis is now dedicated to Pitch
const X_VECTORS = {
  3: 100,
  5: 30,  
  7: 20,
  11: -20,
  13: -30,
};

const PRIMES = [3, 5, 7, 11, 13];
const PRIME_RATIOS = {
  3: new Fraction(3, 2),
  5: new Fraction(5, 4),
  7: new Fraction(7, 4),
  11: new Fraction(11, 8),
  13: new Fraction(13, 8),
};

// --- Generation ---

export const getHarmonicDistance = (coordsA: number[], coordsB: number[] = [0,0,0,0,0]): number => {
  const p3 = coordsA[0] - coordsB[0];
  const p5 = coordsA[1] - coordsB[1];

  // Standard lattice distance logic for generation bounds
  let hexDist = 0;
  if (Math.sign(p3) === Math.sign(p5) && p3 !== 0 && p5 !== 0) {
    hexDist = Math.abs(p3) + Math.abs(p5);
  } else {
    hexDist = Math.max(Math.abs(p3), Math.abs(p5));
  }

  let otherDist = 0;
  for (let i = 2; i < coordsA.length; i++) {
    otherDist += Math.abs(coordsA[i] - coordsB[i]);
  }

  return hexDist + otherDist;
};

export const generateLattice = (settings: AppSettings): { nodes: LatticeNode[], lines: LatticeLine[] } => {
  const baseNodes: Map<string, { coords: number[], ratio: Fraction }> = new Map();
  const queue: { coords: number[], ratio: Fraction }[] = [];

  // 1. Generate Base Set (Normalized 1-2)
  const originCoords = [0, 0, 0, 0, 0];
  const originFrac = new Fraction(1, 1);
  queue.push({ coords: originCoords, ratio: originFrac });
  baseNodes.set(originCoords.join(','), { coords: originCoords, ratio: originFrac });

  const MAX_NODES = 2000;
  let processedCount = 0;

  while (queue.length > 0 && processedCount < MAX_NODES) {
    const current = queue.shift()!;
    processedCount++;
    const { coords, ratio } = current;

    PRIMES.forEach((prime, idx) => {
      if (prime === 7 && !settings.enabledLimits[7]) return;
      if (prime === 11 && !settings.enabledLimits[11]) return;
      if (prime === 13 && !settings.enabledLimits[13]) return;

      [1, -1].forEach(dir => {
        const nextPos = [...coords];
        nextPos[idx] += dir;
        const posKey = nextPos.join(',');

        if (!baseNodes.has(posKey)) {
          const dist = getHarmonicDistance(nextPos);
          if (dist < settings.latticeShells) {
             let nextRatio: Fraction;
             const pRat = PRIME_RATIOS[prime as keyof typeof PRIME_RATIOS];
             if (dir === 1) nextRatio = ratio.mul(pRat).normalize();
             else {
                const invRatio = new Fraction(pRat.d, pRat.n);
                nextRatio = ratio.mul(invRatio).normalize();
             }

             if (nextRatio.n <= settings.maxND && nextRatio.d <= settings.maxND) {
                baseNodes.set(posKey, { coords: nextPos, ratio: nextRatio });
                queue.push({ coords: nextPos, ratio: nextRatio });
             }
          }
        }
      });
    });
  }

  // 2. Expand Vertically (Octaves)
  // We'll create copies of baseNodes for octaves -2 to +2 (or based on canvas size)
  const OCTAVE_RANGE = 2; 
  const nodes: LatticeNode[] = [];
  const nodesMap: Map<string, LatticeNode> = new Map();

  baseNodes.forEach((data, key) => {
      for (let oct = -OCTAVE_RANGE; oct <= OCTAVE_RANGE; oct++) {
          const shiftedRatio = data.ratio.shiftOctave(oct);
          const absoluteRatio = shiftedRatio.n / shiftedRatio.d;

          // ID includes octave to differentiate
          const id = `${key}:${oct}`;

          // Calculate X (Harmonic)
          let x = 0;
          x += data.coords[0] * X_VECTORS[3];
          x += data.coords[1] * X_VECTORS[5];
          x += data.coords[2] * X_VECTORS[7];
          x += data.coords[3] * X_VECTORS[11];
          x += data.coords[4] * X_VECTORS[13];

          // Calculate Y (Pitch)
          // Visual Up (Lower Y) = Higher Pitch. 
          // Base Frequency is Y=0 offset.
          // log2(1) = 0. log2(2) = 1.
          const PITCH_SCALE = 200; // Pixels per octave
          const y = -(Math.log2(absoluteRatio) * PITCH_SCALE);

          const limitTop = getMaxPrime(shiftedRatio.n);
          const limitBottom = getMaxPrime(shiftedRatio.d);
          const maxPrime = Math.max(limitTop, limitBottom);

          const node: LatticeNode = {
              id,
              coords: data.coords,
              ratio: absoluteRatio,
              n: shiftedRatio.n,
              d: shiftedRatio.d,
              label: `${shiftedRatio.n}/${shiftedRatio.d}`,
              x,
              y,
              limitTop,
              limitBottom,
              maxPrime,
              octave: oct
          };
          nodes.push(node);
          nodesMap.set(id, node);
      }
  });

  // 3. Generate Lines (including vertical octave connections)
  const lines: LatticeLine[] = [];

  // Sort for Z-index
  nodes.sort((a, b) => b.maxPrime - a.maxPrime);

  nodes.forEach(node => {
      // Harmonic Neighbors
      PRIMES.forEach((prime, idx) => {
          const neighborCoords = [...node.coords];
          neighborCoords[idx] += 1;
          const key = neighborCoords.join(',');

          if (baseNodes.has(key)) {
             // We need to find which octave of this neighbor is "closest" or "valid"

             // Target Ratio
             const targetVal = node.ratio * (PRIME_RATIOS[prime as keyof typeof PRIME_RATIOS].n / PRIME_RATIOS[prime as keyof typeof PRIME_RATIOS].d);

             // Iterate nearby octaves
             for(let o = node.octave - 1; o <= node.octave + 1; o++) {
                 const targetId = `${key}:${o}`;
                 const target = nodesMap.get(targetId);
                 if (target) {
                     // Check if this is the interval we want (approx)
                     const ratio = target.ratio / node.ratio;
                     const expected = PRIME_RATIOS[prime as keyof typeof PRIME_RATIOS];
                     const expectedVal = expected.n / expected.d;
                     const invExpectedVal = expected.d / expected.n;

                     // Allow slight floating point error
                     const EPSILON = 0.001;
                     // Check regular or inverse
                     if (Math.abs(ratio - expectedVal) < EPSILON || Math.abs(ratio - invExpectedVal) < EPSILON) {
                          lines.push({
                            id: `${node.id}-${target.id}`,
                            x1: node.x,
                            y1: node.y,
                            x2: target.x,
                            y2: target.y,
                            limit: prime
                          });
                     }
                 }
             }
          }
      });

      // 2. Vertical Octave Connections
      // Connect node to node:oct+1
      const octUpId = `${node.coords.join(',')}:${node.octave + 1}`;
      const octUpNode = nodesMap.get(octUpId);
      if (octUpNode) {
          lines.push({
              id: `${node.id}-oct-${node.octave}`,
              x1: node.x,
              y1: node.y,
              x2: octUpNode.x,
              y2: octUpNode.y,
              limit: 1 // Octave "limit" (Identity)
          });
      }
  });

  return { nodes, lines };
};

import React, { useEffect, useRef, useState, useLayoutEffect } from 'react';
import { AppSettings, LatticeNode, LatticeLine } from '../types';
import { generateLattice, getHarmonicDistance } from '../services/LatticeService';
import AudioEngine from '../services/AudioEngine';

interface Props {
  settings: AppSettings;
  audioEngine: AudioEngine;
  onLimitInteraction: (limit: number) => void;
}

interface ActiveTouch {
  id: number;
  nodeId: string; // The "Anchor" node for the current bend
  startX: number;
  startY: number;
  currentX: number;
  currentY: number;

  // Dynamic bending state
  targetNodeId: string | null;
  bendAmount: number; // 0 to 1
}

interface LatchedVoice {
  voiceId: number;
  nodeId: string;
}

const TonalityDiamond: React.FC<Props> = ({ settings, audioEngine, onLimitInteraction }) => {
  const scrollContainerRef = useRef<HTMLDivElement>(null);
  const contentRef = useRef<HTMLDivElement>(null);

  const [data, setData] = useState<{ nodes: LatticeNode[], lines: LatticeLine[] }>({ nodes: [], lines: [] });
  const [activeTouches, setActiveTouches] = useState<Map<number, ActiveTouch>>(new Map());
  const [latchedVoices, setLatchedVoices] = useState<Map<string, number>>(new Map()); // nodeId -> voiceId

  const [lastPlayedCoords, setLastPlayedCoords] = useState<number[]>([0, 0, 0, 0, 0]); 

  const [hasCentered, setHasCentered] = useState(false);

  useEffect(() => {
    const result = generateLattice(settings);
    // Filter out nodes based on visibility, but we need them for logic?
    // Better to filter just visual rendering or keep them all for connectivity?
    // Let's filter visually but keep structure if needed. For now, strict filter.
    const visibleNodes = result.nodes.filter(n => !settings.hiddenLimits.includes(n.maxPrime));
    const visibleLines = result.lines.filter(l => !settings.hiddenLimits.includes(l.limit));
    setData({ nodes: visibleNodes, lines: visibleLines });
  }, [settings]);

  useLayoutEffect(() => {
    if (scrollContainerRef.current && !hasCentered) {
        const center = settings.canvasSize / 2;
        const viewportW = scrollContainerRef.current.clientWidth;
        const viewportH = scrollContainerRef.current.clientHeight;

        scrollContainerRef.current.scrollLeft = center - viewportW / 2;
        scrollContainerRef.current.scrollTop = center - viewportH / 2;
        setHasCentered(true);
    }
  }, [settings.canvasSize, hasCentered]);

  useEffect(() => {
    audioEngine.setPolyphony(settings.polyphony);
  }, [settings.polyphony, audioEngine]);

  const handlePointerDown = (e: React.PointerEvent, node: LatticeNode) => {
    e.preventDefault();
    e.stopPropagation();

    // Tap to stop Latched Voice
    if (latchedVoices.has(node.id)) {
        const voiceId = latchedVoices.get(node.id)!;
        audioEngine.stopVoice(voiceId);
        setLatchedVoices(prev => {
            const next = new Map(prev);
            next.delete(node.id);
            return next;
        });
        return;
    }

    onLimitInteraction(node.maxPrime);
    setLastPlayedCoords(node.coords);

    audioEngine.startVoice(e.pointerId, node.ratio);
    setActiveTouches(prev => {
      const newMap = new Map(prev);
      newMap.set(e.pointerId, {
        id: e.pointerId,
        nodeId: node.id,
        startX: e.clientX,
        startY: e.clientY,
        currentX: e.clientX,
        currentY: e.clientY,
        targetNodeId: null,
        bendAmount: 0
      });
      return newMap;
    });
    (e.target as HTMLElement).setPointerCapture(e.pointerId);
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    if (!activeTouches.has(e.pointerId)) return;
    const touch = activeTouches.get(e.pointerId)!;

    const centerOffset = settings.canvasSize / 2;
    const spacing = settings.buttonSpacingScale;

    // 1. Calculate Vector from Start to Current
    const dx = e.clientX - touch.startX;
    const dy = e.clientY - touch.startY;

    // 2. Vector-based Bend Logic
    if (settings.isPitchBendEnabled) {
        const anchorNode = data.nodes.find(n => n.id === touch.nodeId);
        if (!anchorNode) return;

        const anchorX = anchorNode.x * spacing + centerOffset;
        const anchorY = anchorNode.y * spacing + centerOffset;

        // Find neighbors (connected via lines)
        const connectedLines = data.lines.filter(l => 
            (l.x1 === anchorNode.x && l.y1 === anchorNode.y) || 
            (l.x2 === anchorNode.x && l.y2 === anchorNode.y)
        );

        let bestTarget: LatticeNode | null = null;
        let bestProjection = 0;
        let bestDistSq = 0;

        connectedLines.forEach(line => {
             const isStart = (line.x1 === anchorNode.x && line.y1 === anchorNode.y);
             const nx = isStart ? line.x2 : line.x1;
             const ny = isStart ? line.y2 : line.y1;

             // Visual Vector to neighbor
             const vx = (nx * spacing + centerOffset) - anchorX;
             const vy = (ny * spacing + centerOffset) - anchorY;

             // Dot Product projection
             // Project drag vector onto neighbor vector
             const vMagSq = vx*vx + vy*vy;
             const dot = dx*vx + dy*vy;

             const projection = dot / vMagSq; // 0 to 1 scalar along the line

             if (projection > 0 && projection > bestProjection) {
                 const neighbor = data.nodes.find(n => n.x === nx && n.y === ny);
                 if (neighbor) {
                     bestProjection = projection;
                     bestTarget = neighbor;
                     bestDistSq = vMagSq;
                 }
             }
        });

        // 3. Apply Bend or Handoff
        if (bestTarget && bestTarget.id) {
            // Cap at 1.0 (arrived at neighbor)
            const amount = Math.min(1.0, bestProjection);

            // Calculate frequency: Geometric interpolation
            // F = F_start * (F_target / F_start) ^ amount
            const ratioRatio = bestTarget.ratio / anchorNode.ratio;
            const currentRatio = anchorNode.ratio * Math.pow(ratioRatio, amount);

            audioEngine.glideVoice(e.pointerId, currentRatio, 0.02); // Fast glide for bend responsiveness

            // Check for Handoff (Legato / Glissando)
            // If we are significantly past the midpoint or close to the target, switch anchor
            if (amount >= 0.95) {
                 onLimitInteraction(bestTarget.maxPrime);
                 setLastPlayedCoords(bestTarget.coords);

                 // Update touch state to new anchor
                 setActiveTouches(prev => {
                     const newMap = new Map(prev);
                     newMap.set(e.pointerId, {
                         ...touch,
                         nodeId: bestTarget!.id,
                         // Reset start to new node position to allow continuous bending
                         // We need screen coords of the new node
                         startX: e.clientX, // Resetting startX/Y to current assumes we are AT the node. 
                         // But we might be slightly off. Ideally, we snap the 'virtual' start to the node center.
                         startY: e.clientY,
                         currentX: e.clientX,
                         currentY: e.clientY,
                         targetNodeId: null,
                         bendAmount: 0
                     });
                     return newMap;
                 });
            } else {
                 // Just update visual bend
                 setActiveTouches(prev => {
                     const newMap = new Map(prev);
                     newMap.set(e.pointerId, {
                         ...touch,
                         currentX: e.clientX,
                         currentY: e.clientY,
                         targetNodeId: bestTarget!.id,
                         bendAmount: amount
                     });
                     return newMap;
                 });
            }
        } else {
            // No valid target, stick to anchor (or minor wobble)
            setActiveTouches(prev => {
                 const newMap = new Map(prev);
                 newMap.set(e.pointerId, {
                     ...touch,
                     currentX: e.clientX,
                     currentY: e.clientY,
                     targetNodeId: null,
                     bendAmount: 0
                 });
                 return newMap;
             });
        }
    }
  };

  const handlePointerUp = (e: React.PointerEvent) => {
    const touch = activeTouches.get(e.pointerId);

    // --- Momentum Logic ---
    // If momentum enabled, latch the note at its CURRENT pitch (even if bent)
    if (settings.isMomentumEnabled && touch) {
         // Latch the anchor node
         // If bent halfway, maybe we should latch the target? 
         // For now, latch the current Anchor (which updates on handoff)
         const nodeToLatch = touch.nodeId;

         setLatchedVoices(prev => {
            const newMap = new Map(prev);
            newMap.set(nodeToLatch, e.pointerId);
            return newMap;
         });

         // Voice keeps running, remove touch tracker
         setActiveTouches(prev => {
            const newMap = new Map(prev);
            newMap.delete(e.pointerId);
            return newMap;
         });
    } else {
        audioEngine.stopVoice(e.pointerId);
        setActiveTouches(prev => {
          const newMap = new Map(prev);
          newMap.delete(e.pointerId);
          return newMap;
        });
    }
  };

  const getColor = (limit: number): string => settings.colors[limit] || '#64748b';

  const baseSize = 60 * settings.buttonSizeScale;
  const touches: ActiveTouch[] = Array.from(activeTouches.values());
  const centerOffset = settings.canvasSize / 2;
  const spacing = settings.buttonSpacingScale;

  const activeNodeIds = new Set([...touches.map(t => t.nodeId), ...latchedVoices.keys()]);

  return (
    <div 
        ref={scrollContainerRef}
        className="w-full h-full overflow-auto bg-slate-950 relative"
        style={{ touchAction: 'none' }}
    >
        <div 
            ref={contentRef}
            className="relative"
            style={{ 
                width: settings.canvasSize, 
                height: settings.canvasSize,
            }}
        >
            {/* SVG Layer for Lines */}
            <svg className="absolute top-0 left-0 w-full h-full pointer-events-none" style={{ zIndex: 0 }}>
                {data.lines.map(line => {
                    const x1 = line.x1 * spacing + centerOffset;
                    const y1 = line.y1 * spacing + centerOffset;
                    const x2 = line.x2 * spacing + centerOffset;
                    const y2 = line.y2 * spacing + centerOffset;
                    const color = getColor(line.limit);

                    // Only show lines connected to active/focused nodes or high level grid
                    // To avoid clutter with the vertical layout

                    return (
                        <line 
                            key={line.id}
                            x1={x1} y1={y1} x2={x2} y2={y2}
                            stroke={color}
                            strokeWidth={line.limit === 1 ? 4 : 2} // Thicker for Octaves
                            strokeOpacity={line.limit === 1 ? 0.4 : 0.2}
                            strokeDasharray={line.limit === 1 ? "5,5" : "0"} // Dashed for Octaves
                        />
                    );
                })}

                {/* Active Pitch Bend Lines (Straight) */}
                {touches.map(touch => {
                    if (!touch.targetNodeId || !touch.nodeId) return null;
                    const startNode = data.nodes.find(n => n.id === touch.nodeId);
                    const targetNode = data.nodes.find(n => n.id === touch.targetNodeId);
                    if (!startNode || !targetNode) return null;

                    const x1 = startNode.x * spacing + centerOffset;
                    const y1 = startNode.y * spacing + centerOffset;
                    const x2 = targetNode.x * spacing + centerOffset;
                    const y2 = targetNode.y * spacing + centerOffset;

                    return (
                        <line 
                           key={`bend-${touch.id}`}
                           x1={x1} y1={y1} x2={x2} y2={y2}
                           stroke="white"
                           strokeWidth={4}
                           strokeOpacity={0.6 + (touch.bendAmount * 0.4)}
                        />
                    );
                })}
            </svg>

            {/* Nodes Layer */}
            {data.nodes.map((node) => {
                const activeTouch = touches.find(t => t.nodeId === node.id);
                const isLatched = latchedVoices.has(node.id);
                const isActive = !!activeTouch || isLatched;
                const isTarget = touches.some(t => t.targetNodeId === node.id);

                const left = node.x * spacing + centerOffset;
                const top = node.y * spacing + centerOffset;

                const cTop = getColor(node.limitTop);
                const cBottom = getColor(node.limitBottom);
                const background = `linear-gradient(to bottom, ${cTop} 50%, ${cBottom} 50%)`;

                const layerIndex = settings.layerOrder.indexOf(node.maxPrime);
                const zIndex = isActive ? 100 : (10 + layerIndex);

                let scale = 1.0;
                let opacity = 0.95;

                if (settings.isVoiceLeadingEnabled) {
                  const dist = getHarmonicDistance(node.coords, lastPlayedCoords);

                  // Modify distance check: Include Pitch Proximity?
                  // For now, stick to harmonic distance + active state
                  if (!isActive && !isTarget) {
                    const falloff = settings.voiceLeadingStrength; 
                    const visibility = Math.max(0.25, 1 - (dist * falloff));
                    scale = Math.max(0.4, visibility);
                    opacity = Math.max(0.15, visibility);
                  } else {
                    scale = 1.2; 
                    opacity = 1.0;
                  }
                } else {
                    scale = (isActive || isTarget) ? 1.2 : 1.0;
                    opacity = (isActive || isTarget) ? 1.0 : 0.95;
                }

                return (
                    <div
                        key={node.id}
                        className="absolute flex items-center justify-center shadow-md cursor-pointer touch-none select-none transition-transform duration-100 ease-out"
                        style={{
                            left: `${left}px`,
                            top: `${top}px`,
                            width: `${baseSize}px`,
                            height: `${baseSize}px`,
                            background: background,
                            borderRadius: settings.buttonShape,
                            transform: `translate(-50%, -50%) scale(${scale})`,
                            boxShadow: isActive ? `0 0 35px white` : '0 4px 6px rgba(0,0,0,0.6)',
                            zIndex: zIndex,
                            opacity: opacity,
                            border: isLatched ? '3px solid white' : (isActive ? '2px solid white' : '2px solid rgba(255,255,255,0.3)'),
                            filter: isActive ? 'brightness(1.3)' : 'none'
                        }}
                        onPointerDown={(e) => handlePointerDown(e, node)}
                        onPointerMove={handlePointerMove}
                        onPointerUp={handlePointerUp}
                        onPointerLeave={handlePointerUp}
                        onPointerCancel={handlePointerUp}
                    >
                        <div className={`flex flex-col w-full h-full text-white font-bold leading-none text-shadow-sm transition-opacity ${scale < 0.6 ? 'opacity-0' : 'opacity-100'}`}>
                            <span className="flex-1 flex items-center justify-center pt-1" style={{ fontSize: '11px' }}>{node.n}</span>
                            <span className="flex-1 flex items-center justify-center pb-1 border-t border-white/20" style={{ fontSize: '11px' }}>{node.d}</span>
                        </div>
                    </div>
                );
            })}
        </div>
    </div>
  );
};

export default TonalityDiamond;
